def classify(count, scope, beneficiary=None):
    if scope == "COMMON":
        return {"ONE":"KINGSHIP", "FEW":"ARISTOCRACY", "MANY":"POLITY"}[count]
    if count == "ONE" and beneficiary == "MONARCH":
        return "TYRANNY"
    if beneficiary == "WEALTHY":
        return "OLIGARCHY"
    if beneficiary == "NEEDY":
        return "DEMOCRACY"
    return "UNRESOLVED"

cases = {
  "one_common": classify("ONE", "COMMON"),
  "few_common": classify("FEW", "COMMON"),
  "many_common": classify("MANY", "COMMON"),
  "wealthy_majority": classify("MANY", "PRIVATE", "WEALTHY"),
  "needy_minority": classify("FEW", "PRIVATE", "NEEDY"),
  "private_monarch": classify("ONE", "PRIVATE", "MONARCH")
}
result = cases
